module softmax (
  input clk,
  input rst_n,
  input start,
  input [8:0] n,
  output reg [7:0] s_addr,
  input signed [12:0] s_data,
  output reg w_valid,
  output reg [7:0] w_index,
  output reg [15:0] w_data,
  output reg busy
);

  localparam IDLE = 0, PASS1 = 1, PASS2 = 2, PASS3_RECIP = 3, PASS3_EMIT = 4;

  reg [2:0] state;
  reg [8:0] n_reg;
  reg signed [12:0] mx;
  reg [15:0] m;
  reg [4:0] k;

  reg [12:0] score_buffer [0:255];
  reg [15:0] exp_buffer [0:255];
  reg [25:0] sum_exp;

  reg [8:0] pass1_send_addr, pass1_receive_addr;
  reg [1:0] pass1_startup_delay;

  reg [8:0] pass2_send_idx, pass2_receive_idx;

  reg [8:0] pass3_emit_idx;
  reg recip_sent;

  wire [15:0] expu_y;
  wire expu_valid_out;
  reg signed [12:0] expu_x;
  reg expu_valid_in;

  wire [16:0] recip_y;
  wire [4:0] recip_k;
  wire recip_valid_out;
  reg recip_valid_in;

  wire [47:0] product = {exp_buffer[pass3_emit_idx], 15'b0} * m;
  wire [47:0] shifted = product >> (42 - k);

  expu expu_inst (
    .clk(clk),
    .rst_n(rst_n),
    .x(expu_x),
    .valid_in(expu_valid_in),
    .y(expu_y),
    .valid_out(expu_valid_out)
  );

  recip recip_inst (
    .clk(clk),
    .rst_n(rst_n),
    .x(sum_exp),
    .valid_in(recip_valid_in),
    .y(recip_y),
    .k(recip_k),
    .valid_out(recip_valid_out)
  );

  always @(posedge clk) begin
    if (!rst_n) begin
      state <= IDLE;
      busy <= 0;
      w_valid <= 0;
      expu_valid_in <= 0;
      recip_valid_in <= 0;
      n_reg <= 0;
      mx <= 13'sh8000;
      m <= 0;
      k <= 0;
      sum_exp <= 0;
      pass1_send_addr <= 0;
      pass1_receive_addr <= 0;
      pass1_startup_delay <= 0;
      pass2_send_idx <= 0;
      pass2_receive_idx <= 0;
      pass3_emit_idx <= 0;
      recip_sent <= 0;
      s_addr <= 0;
    end else begin
      w_valid <= 0;
      expu_valid_in <= 0;
      recip_valid_in <= 0;

      case (state)
        IDLE: begin
          if (start) begin
            state <= PASS1;
            busy <= 1;
            n_reg <= n;
            mx <= 13'sh8000;
            s_addr <= 0;
            pass1_send_addr <= 0;
            pass1_receive_addr <= 0;
            pass1_startup_delay <= 0;
          end
        end

        PASS1: begin
          if (pass1_send_addr < n_reg) begin
            s_addr <= pass1_send_addr;
            pass1_send_addr <= pass1_send_addr + 1;
          end

          if (pass1_startup_delay < 2) begin
            pass1_startup_delay <= pass1_startup_delay + 1;
          end else if (pass1_receive_addr < n_reg) begin
            score_buffer[pass1_receive_addr] <= s_data;
            if (s_data > mx) begin
              mx <= s_data;
            end
            pass1_receive_addr <= pass1_receive_addr + 1;
          end else begin
            state <= PASS2;
            pass2_send_idx <= 0;
            pass2_receive_idx <= 0;
            sum_exp <= 0;
          end
        end

        PASS2: begin
          if (pass2_send_idx < n_reg) begin
            expu_x <= score_buffer[pass2_send_idx] - mx;
            expu_valid_in <= 1;
            pass2_send_idx <= pass2_send_idx + 1;
          end

          if (expu_valid_out) begin
            exp_buffer[pass2_receive_idx] <= expu_y;
            sum_exp <= sum_exp + {10'b0, expu_y};
            pass2_receive_idx <= pass2_receive_idx + 1;
          end

          if (pass2_receive_idx == n_reg && pass2_send_idx >= n_reg) begin
            state <= PASS3_RECIP;
            recip_sent <= 0;
          end
        end

        PASS3_RECIP: begin
          if (!recip_sent) begin
            recip_valid_in <= 1;
            recip_sent <= 1;
          end

          if (recip_valid_out) begin
            m <= recip_y[15:0];
            k <= recip_k;
            state <= PASS3_EMIT;
            pass3_emit_idx <= 0;
          end
        end

        PASS3_EMIT: begin
          if (pass3_emit_idx < n_reg) begin
            w_valid <= 1;
            w_index <= pass3_emit_idx;

            if (shifted > 48'h000000007FFF) begin
              w_data <= 16'h7FFF;
            end else begin
              w_data <= shifted[15:0];
            end

            pass3_emit_idx <= pass3_emit_idx + 1;
          end else begin
            state <= IDLE;
            busy <= 0;
          end
        end
      endcase
    end
  end

endmodule

